void Menu(void)//閼挎粌宕熼崙鑺ユ殶
{



                if(key1_flag)
                {

                    func_index = table_dispaly[func_index].up;    //閸氭垳绗傜紙?
                    key1_clear();
                }
                if(key2_flag)
                {

                    func_index = table_dispaly[func_index].down;    //閸氭垳绗呯紙?
                     key2_clear();

                }
                if(key3_flag)
                {

                    func_index = table_dispaly[func_index].enter;    //绾喛顓?
                    key3_clear();

                }


            if (func_index != last_index)
            {
                current_operation_index = table_dispaly[func_index].current_operation;

                ips200_clear();
                (*current_operation_index)();//閹笛嗩攽瑜版挸澧犻幙宥勭稊閸戣姤鏆?
                last_index = func_index;

            }
            else
            {
                (*current_operation_index)();//閹笛嗩攽瑜版挸澧犻幙宥勭稊閸戣姤鏆?
            }
  }


