////////////////////////////////////////////////////////////////////////////////////////////////////////缁楊兛绗佺仦?//////////////////////////////////////////////////////////////////////////////////////////////////////////

void fun_a31()//瀵板懓鐨熺化缁樻殶
{

    if(key4_flag)
    {
        flag++;
        if(flag>4)
        {
            flag=0;
        }
        key4_clear();
    }
    ips200_show_float(8*0, 16*1, roll_balance_cascade.posture_value.mechanical_zero, 2,1);   ips200_show_int(8*10, 16*1, flag, 1);
    ips200_show_float(8*0, 16*2, zero_set, 3,1);
    ips200_draw_line(0,48,232,48,RGB565_BLUE);
    ips200_show_float(8*0, 16*4, step_3, 2,1);
    ips200_show_float(8*0, 16*5, step_set, 2,1);
    ips200_draw_line(0,96,232,96,RGB565_BLUE);
    ips200_show_float(8*0, 16*7, stl_kp3, 2,1);
    ips200_show_float(8*0, 16*8, stl_kp_set, 2,1);
    switch(flag)
    {
        case 1:
            if(key2_flag)
            {
                zero_set+=2;           //閺堢儤顫梿鍓佸仯
                key2_clear();
            }
            if(key1_flag)
            {
                zero_set-=2;
                key1_clear();
            }

            break;
        case 2:
            if(key2_flag)
            {
                step_set+=1;           //閹垰顕遍柅鐔峰缁粯鏆?
                key2_clear();
            }
            if(key1_flag)
            {
                step_set-=1;           //閹垰顕遍柅鐔峰缁粯鏆?
                key1_clear();
            }

            break;
        case 3:
            if(key2_flag)
            {
                stl_kp_set+=1;           //閺傤垰娼堕崚鈺冮兇閺?
                key2_clear();
            }
            if(key1_flag)
            {
                stl_kp_set-=1;           //閺傤垰娼堕崚鈺冮兇閺?
                key1_clear();
            }

            break;
        case 4:
            if(key1_flag)
            {
                  static bool once = false;      //娣囨繆鐦夐崣顏囩ゴ閸婇棿绔村▎?
                    if (!once)
                    {
                      balance_cascade_init();   //闁插秵鏌婇崚鍡涘帳閺堢儤顫梿鍓佸仯閸欏倹鏆?
                      step_3=step_set;
                      stl_kp3=stl_kp_set;
                      once = true;
                      flag=0;
                    }
                key1_clear();
            }

            break;
    }




}

