void fun_c32()//RUN_2 閳?瀵偓婵顫栭惄?閿涘牊鍎荤€电厧娲栭弨鎾呯礆
{
    /* 婵″倹鐏夋潻妯烘躬瑜版洖鍩楅悩鑸碘偓渚婄礉閸忓牐鍤滈崝銊ょ箽鐎涙ê鍟€閸ョ偞鏂?*/
    if(gd_mode == guandao_record_mode)
    {
        guandao_flash_record();
        gd_mode = guandao_pass_mode;
        Buzzer_check(100);
        ips200_clear();
    }

    /* 缁屾椽妫?閳?鐏忔繆鐦禒?Flash 閸旂姾娴囩捄顖氱窞 */
//    Motor_Standard_Speed = 383;           // 缁夋垹娲?
    Motor_Standard_Speed = 33;              // 缁夋垹娲?(闂傤厾骞嗛柅鐔峰)
    dis_record = 0.03;                      // 缁夋垹娲?閿?cm  婢堆勵洤30m
    if(gd_mode == guandao_pass_mode)
    {
        guandao_flash_load();
        if(guandao_index > 0)
        {
            data_x.f = 0; data_y.f = 0;
            guandao_lucheng = 0;
            c_error = 0; int_c_error = 0;//閸戝搫闆?鏉╂稑鍙嗛惄瀵稿殠閺冭埖濡?int_c_error 濞撳懘娴傞敍灞介泦闁挾袧閸掑棔绗夌敮锕€鍙嗛惄瀵稿殠
            guandao_last_cnt = 0; guandao_new_cnt = 0;
            gd_mode = guandao_load_mode;
            SUB_flag = 2;
            step = 2; stl_kp = 8;
            ips200_clear();
        }
    }

    ips200_show_string(0,  16*0, ">>> RUN SUB2 <<<");
    ips200_show_string(0,  16*1, "Status: ");
    ips200_show_int(8*10, 16*1, gd_mode, 2);
    ips200_show_string(0,  16*2, "Points: ");
    ips200_show_int(8*10, 16*2, guandao_index, 5);
    ips200_show_string(0,  16*4, "ENTER=back to menu");
}

void fun_c33()//RUN_3 閳?瀵偓婵顫栭惄?
{
    if(gd_mode == guandao_record_mode)
    {
        guandao_flash_record();
        gd_mode = guandao_pass_mode;
        Buzzer_check(100);
        ips200_clear();
    }

    Motor_Standard_Speed = 1100;            // 缁夋垹娲?
    dis_record = 0.20;                      // 缁夋垹娲?閿?0cm
    if(gd_mode == guandao_pass_mode)
    {
        guandao_flash_load();
        if(guandao_index > 0)
        {
            data_x.f = 0; data_y.f = 0;
            guandao_lucheng = 0;
            c_error = 0; int_c_error = 0;
            guandao_last_cnt = 0; guandao_new_cnt = 0;
            gd_mode = guandao_load_mode;
            SUB_flag = 3;
            step = step_3; stl_kp = stl_kp3;
            ips200_clear();
        }
    }

    ips200_show_string(0,  16*0, ">>> RUN SUB3 <<<");
    ips200_show_string(0,  16*1, "Status: ");
    ips200_show_int(8*10, 16*1, gd_mode, 2);
    ips200_show_string(0,  16*2, "Points: ");
    ips200_show_int(8*10, 16*2, guandao_index, 5);
    ips200_show_string(0,  16*4, "ENTER=back to menu");
}

